// More file formats share the immutable snapshot generated by Preview & export.
export function createExportOptions({api,getExport,toast}){
  const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const link=document.createElement('link');link.rel='stylesheet';link.href='/export-options.css';document.head.append(link);
  const host=document.createElement('div');host.className='export-options';host.id='exportOptions';$('exportFormat').closest('label').after(host);
  let formats=[],generation=0,cut=false,busy=false;
  const numeric=(id,label,value,min,max,step=1)=>`<label>${label}<input id="${id}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${value}" required></label>`;
  host.innerHTML=`<div id="imageSettings" hidden><div class="export-grid">${numeric('imageDpi','Resolution (DPI)',300,100,2000)}${numeric('imageWidth','Thread line width (mm)',.3,.01,5,'any')}</div></div>
  <div id="zipSettings" hidden><label>Bundle filename<input id="bundleName" maxlength="80" placeholder="Use design name" autocomplete="off"></label><fieldset><legend>Files to include</legend><div id="zipFormats" class="export-formats"></div></fieldset>
  <fieldset><legend>Repeated layout</legend><div class="export-grid">${numeric('repeatX','Copies across',1,1,20)}${numeric('repeatY','Copies down',1,1,20)}${numeric('spacingX','Horizontal spacing (mm)',100,-1000,1000,'any')}${numeric('spacingY','Vertical spacing (mm)',100,-1000,1000,'any')}</div><p class="caption">Spacing is between copy origins. Negative values reverse direction; values smaller than the design size overlap copies. Each thread color sews across all copies before the next color.</p><label>Destination<select id="bundleDestination"><option value="pp1">Brother PP1 · 100 × 100 mm</option><option value="other">Another machine · review finished size</option></select></label><p id="repeatEstimate" class="caption"></p></fieldset>
  <fieldset id="bundleImageSettings" hidden><legend>Images in the ZIP</legend><div class="export-grid"><div id="simpleZipDpi">${numeric('bundleSimpleDpi','Simple PNG resolution (DPI)',300,100,2000)}</div><div id="realisticZipDpi">${numeric('bundleRealisticDpi','Realistic PNG resolution (DPI)',300,100,2000)}</div><div id="simpleZipWidth">${numeric('bundleLineWidth','Simple PNG line width (mm)',.3,.01,5,'any')}</div></div></fieldset>
  <p class="caption">Machine files and PNGs contain the repeated layout. Editable SVG and project backup retain the single original design. Machine files use the document export rotation; images use the artwork orientation.</p></div>
  <div id="imageBackground" hidden><div class="export-grid"><label>Image background<select id="exportBackground"><option value="transparent">Transparent</option><option value="fabric">Design fabric color</option><option value="custom">Custom color</option></select></label><label id="exportColorLabel" hidden>Background color<input id="exportColor" type="color" value="#ffffff"></label></div><p class="caption">Background color is for the image only and adds no stitches.</p></div><p id="exportMessage" role="status"></p><div id="exportResult" class="export-result" hidden></div>`;
  const selected=()=>[...host.querySelectorAll('[data-zip]:checked')].map(e=>e.dataset.zip);
  function invalidate(){generation++;$('formatDownload').hidden=true;$('exportResult').hidden=true;$('exportMessage').textContent='';}
  function visibility(){const mode=$('exportFormat').value,zip=mode==='zip',image=mode==='png'||mode==='png-realistic',keys=selected();host.hidden=!zip&&!image;$('imageSettings').hidden=!image;$('imageWidth').closest('label').hidden=mode!=='png';$('zipSettings').hidden=!zip;const simple=keys.includes('png_simple'),real=keys.includes('png_realistic');$('bundleImageSettings').hidden=!(simple||real);$('simpleZipDpi').hidden=!simple;$('simpleZipWidth').hidden=!simple;$('realisticZipDpi').hidden=!real;$('imageBackground').hidden=!(image||zip&&(simple||real));$('exportColorLabel').hidden=$('exportBackground').value!=='custom';estimate();}
  function estimate(){const p=getExport()?.preview;if(!p)return;const x=Number($('repeatX').value),y=Number($('repeatY').value),w=p.width+Math.abs(Number($('spacingX').value))*(x-1),h=p.height+Math.abs(Number($('spacingY').value))*(y-1);$('repeatEstimate').textContent=`Approximate layout: ${w.toFixed(1)} × ${h.toFixed(1)} mm · ${x*y} copies. Finished stitches are checked when prepared.`;}
  host.addEventListener('input',()=>{invalidate();visibility();});$('exportFormat').addEventListener('change',()=>{invalidate();visibility();});
  function read(){for(const el of host.querySelectorAll('input')){if(el.closest('[hidden]'))continue;if(!el.reportValidity())throw new Error('Check the highlighted export setting.');}const n=id=>Number($(id).value),mode=$('exportFormat').value,common={background:$('exportBackground').value,color:$('exportColor').value};if(mode!=='zip')return {...common,dpi:n('imageDpi'),...(mode==='png'?{lineWidth:n('imageWidth')}:{})};const keys=selected();return {...common,filename:$('bundleName').value,formats:keys,xRepeats:n('repeatX'),yRepeats:n('repeatY'),xSpacing:n('spacingX'),ySpacing:n('spacingY'),...(keys.includes('png_simple')?{simpleDpi:n('bundleSimpleDpi'),lineWidth:n('bundleLineWidth')}:{}),...(keys.includes('png_realistic')?{realisticDpi:n('bundleRealisticDpi')}:{}),destination:$('bundleDestination').value};}
  function canvas(p){const c=$('bundleCanvas'),g=c.getContext('2d');c.width=1000;c.height=520;g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);const scale=Math.min(960/Math.max(1,p.width),480/Math.max(1,p.height)),dx=(1000-p.width*scale)/2-p.bounds[0]*scale,dy=(520-p.height*scale)/2-p.bounds[1]*scale;g.lineWidth=Math.max(.65,.16*scale);g.lineCap='round';let color=-1;for(const [x1,y1,x2,y2,k] of p.segments){if(k!==color){if(color!==-1)g.stroke();g.beginPath();g.strokeStyle=p.threads[k].color;color=k;}g.moveTo(x1*scale+dx,y1*scale+dy);g.lineTo(x2*scale+dx,y2*scale+dy);}if(color!==-1)g.stroke();}
  $('exportFormatBtn').onclick=async()=>{const current=getExport(),mode=$('exportFormat').value;if(!current||busy)return;let options;try{options=read();}catch(e){toast(e.message);return;}invalidate();const token=generation;busy=true;$('exportFormatBtn').disabled=true;$('exportFormatBtn').textContent='Preparing file…';host.querySelectorAll('input,select').forEach(e=>e.disabled=true);$('exportFormat').disabled=true;try{const r=await api('/api/export-format',{id:current.id,format:mode,...(['png','png-realistic','zip'].includes(mode)?{options}:{})});if(generation!==token||getExport()?.id!==current.id)return;$('formatDownload').href=r.url;$('formatDownload').hidden=false;if(r.preview){const p=r.preview;$('exportResult').innerHTML=`<strong>Finished layout: ${p.width.toFixed(1)} × ${p.height.toFixed(1)} mm</strong><p>${p.stitches.toLocaleString()} stitches · ${p.threads.length} thread steps · ${p.stops} stops · ${p.trims} trims</p><canvas id="bundleCanvas" aria-label="Finished repeated stitch layout"></canvas><p>${esc(r.note)}</p><ul>${r.files.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`;canvas(p);}else if(r.pixels){$('exportResult').innerHTML=`<strong>${r.pixels[0]} × ${r.pixels[1]} pixels · ${options.dpi} DPI</strong><p><img src="${esc(r.url)}" alt="Prepared embroidery image"></p>`;}$('exportResult').hidden=!r.preview&&!r.pixels;$('exportMessage').className='';$('exportMessage').textContent='Ready to download.';}catch(e){$('exportMessage').className='export-error';$('exportMessage').textContent=e.message;toast(e.message);}finally{busy=false;$('exportFormatBtn').disabled=false;$('exportFormatBtn').textContent='Prepare download';host.querySelectorAll('input,select').forEach(e=>e.disabled=false);$('exportFormat').disabled=false;applyCut();}};
  function applyCut(){host.querySelectorAll('[data-zip]').forEach(e=>{const allowed=!cut||['exp','inf','svg','project','threadlist','png_simple','png_realistic'].includes(e.dataset.zip);e.disabled=!allowed;if(!allowed)e.checked=false;});$('bundleDestination').disabled=cut;if(cut)$('bundleDestination').value='other';}
  return {formats(f){formats=f.zipFormats;$('zipFormats').innerHTML=formats.map(f=>`<label class="check"><input type="checkbox" data-zip="${esc(f.key)}" ${['pes','svg','project','threadlist'].includes(f.key)?'checked':''}>${esc(f.label)}</label>`).join('');applyCut();visibility();},refresh(){invalidate();const next=!!getExport()?.cutwork;if(next!==cut){cut=next;$('bundleDestination').value=cut?'other':'pp1';host.querySelectorAll('[data-zip]').forEach(e=>e.checked=(cut?['exp','inf','svg','project','threadlist']:['pes','svg','project','threadlist']).includes(e.dataset.zip));}applyCut();visibility();}};
}
